       </svg>\n        <span>返回</span>\n      </button>\n\n      <!-- 角色信息 -->\n      <div class=\"info-section\">\n        <!-- 角色名 -->\n        <h2 class=\"char-name\">{{ name }}</h2>\n\n        <!-- 一句话介绍 -->\n        <p class=\"char-intro\">{{ meta?.intro }}</p>\n\n        <!-- 身份标签 -->\n        <div class=\"meta-row\">\n          <svg class=\"meta-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\" />\n            <circle cx=\"12\" cy=\"7\" r=\"4\" />\n          </svg>\n          <span class=\"meta-text\">{{ meta?.identity }}</span>\n        </div>\n\n        <!-- 关系状态 -->\n        <div class=\"meta-row\">\n          <svg class=\"meta-icon\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n            <path d=\"M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z\" />\n          </svg>\n          <span class=\"relation-badge\" :class=\"relationClass\">{{ charData.关系状态 }}</span>\n        </div>\n\n        <!-- 好感度进度条 -->\n        <div class=\"favor-section\">\n          <div class=\"favor-header\">\n            <span class=\"favor-label\">好感度</span>\n            <span class=\"favor-value\">{{ charData.好感度 }}</span>\n          </div>\n          <div class=\"favor-track\">\n            <div\n              class=\"favor-fill\"\n              :style=\"{ width: progressWidth, background: progressGradient }\"\n            ></div>\n          </div>\n        </div>\n\n        <!-- 关键事件列表 -->\n        <div v-if=\"events.length > 0\" class=\"events-section\">\n          <span class=\"events-title\">关键事件</span>\n          <div class=\"events-list\">\n            <div\n              v-for=\"event in events\"\n              :key=\"event.name\"\n              class=\"event-item\"\n            >\n              <svg v-if=\"event.done\" class=\"event-icon done\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <polyline points=\"20,6 9,17 4,12\" />\n              </svg>\n              <svg v-else class=\"event-icon pending\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\">\n                <circle cx=\"12\" cy=\"12\" r=\"10\" />\n              </svg>\n              <span class=\"event-text\" :class=\"{ done: event.done }\">{{ event.name }}</span>\n            </div>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n</template>\n\n<script setup lang=\"ts\">\nimport { useStatusStore, CHARACTER_LIST, type CharacterMeta } from '../store';\n\nconst props = defineProps<{ name: string }>();\ndefineEmits<{ back: [] }>();\n\nconst store = useStatusStore();\n\nconst meta = computed<CharacterMeta | undefined>(() =>\n  CHARACTER_LIST.find(c => c.name === props.name),\n);\n\nconst charData = computed(() => store.getCharacter(props.name));\n\nconst events = computed(() =>\n  Object.entries(charData.value.关键事件).map(([name, done]) => ({ name, done })),\n);\n\n/** 卡片背景：角色主题色渐变模拟图片 */\nconst cardBgStyle = computed(() => {\n  const baseColor = meta.value?.color ?? '#1a1a2e';\n  const image = meta.value?.image;\n  if (image) {\n    return {\n      backgroundColor: baseColor,\n      backgroundImage: `linear-gradient(135deg, ${baseColor}66 0%, ${baseColor}22 100%), url(\"${image}\")`,\n      backgroundPosition: 'center right',\n      backgroundSize: 'cover',\n    };\n  }\n  return {\n    background: `linear-gradient(135deg, ${baseColor} 0%, ${baseColor}dd 40%, ${baseColor}88 70%, ${baseColor}44 100%)`,\n  };\n});\n\nconst progressWidth = computed(() => {\n  const favor = charData.value.好感度;\n  const normalized = Math.max(2, Math.min(100, ((favor + 100) / 200) * 100));\n  return `${normalized}%`;\n});\n\nconst progressGradient = computed(() => {\n  return 'linear-gradient(90deg, #4a9eff 0%, #a855f7 50%, #ff6b9d 100%)';\n});\n\nconst relationClass = computed(() => {\n  switch (charData.value.关系状态) {\n    case '恋人':\n      return 'relation-lover';\n    case '暧昧':\n      return 'relation-ambiguous';\n    case '熟悉':\n      return 'relation-familiar';\n    case '决裂':\n    case '封心':\n    case '疏远':\n      return 'relation-broken';\n    default:\n      return 'relation-default';\n  }\n});\n</script>\n\n<style scoped>\n.char-detail-card {\n  position: relative;\n  width: 100%;\n  min-height: 200px;\n  border-radius: 16px;\n  overflow: hidden;\n}\n\n.card-overlay {\n  position: absolute;\n  inset: 0;\n  background: linear-gradient(to right, rgba(10, 10, 20, 0.95) 0%, rgba(10, 10, 20, 0.7) 50%, transparent 100%);\n  z-index: 1;\n}\n\n.card-content {\n  position: relative;\n  z-index: 2;\n  padding: 16px;\n  display: flex;\n  flex-direction: column;\n  gap: 10px;\n}\n\n.back-btn {\n  display: flex;\n  align-items: center;\n  gap: 4px;\n  background: none;\n  border: none;\n  color: rgba(255, 255, 255, 0.6);\n  font-size: 12px;\n  cursor: pointer;\n  padding: 4px 8px;\n  border-radius: 6px;\n  transition: all 0.2s;\n  align-self: flex-start;\n}\n\n.back-btn:hover {\n  color: #fff;\n  background: rgba(255, 255, 255, 0.1);\n}\n\n.back-icon {\n  width: 12px;\n  height: 12px;\n}\n\n.info-section {\n  display: flex;\n  flex-direction: column;\n  gap: 8px;\n  max-width: 70%;\n}\n\n.char-name {\n  font-size: 22px;\n  font-weight: 700;\n  color: #fff;\n  margin: 0;\n  text-shadow: 0 2px 8px rgba(0, 0, 0, 0.5);\n}\n\n.char-intro {\n  font-size: 12px;\n  color: rgba(255, 255, 255, 0.7);\n  margin: 0;\n  line-height: 1.5;\n  font-style: italic;\n}\n\n.meta-row {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.meta-icon {\n  width: 12px;\n  height: 12px;\n  color: rgba(255, 255, 255, 0.4);\n  flex-shrink: 0;\n}\n\n.meta-text {\n  font-size: 11px;\n  color: rgba(255, 255, 255, 0.6);\n}\n\n.relation-badge {\n  font-size: 11px;\n  padding: 2px 8px;\n  border-radius: 10px;\n}\n\n.relation-lover {\n  background: rgba(236, 72, 153, 0.2);\n  color: #f9a8d4;\n}\n\n.relation-ambiguous {\n  background: rgba(168, 85, 247, 0.2);\n  color: #c4b5fd;\n}\n\n.relation-familiar {\n  background: rgba(59, 130, 246, 0.2);\n  color: #93c5fd;\n}\n\n.relation-broken {\n  background: rgba(239, 68, 68, 0.2);\n  color: #fca5a5;\n}\n\n.relation-default {\n  background: rgba(255, 255, 255, 0.1);\n  color: rgba(255, 255, 255, 0.5);\n}\n\n.favor-section {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.favor-header {\n  display: flex;\n  align-items: center;\n  justify-content: space-between;\n}\n\n.favor-label {\n  font-size: 11px;\n  color: rgba(255, 255, 255, 0.5);\n}\n\n.favor-value {\n  font-size: 12px;\n  font-weight: 600;\n  color: rgba(255, 255, 255, 0.8);\n}\n\n.favor-track {\n  height: 5px;\n  background: rgba(255, 255, 255, 0.08);\n  border-radius: 3px;\n  overflow: hidden;\n}\n\n.favor-fill {\n  height: 100%;\n  border-radius: 3px;\n  transition: width 0.5s ease;\n  min-width: 2px;\n}\n\n.events-section {\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  margin-top: 4px;\n}\n\n.events-title {\n  font-size: 11px;\n  font-weight: 500;\n  color: rgba(255, 255, 255, 0.5);\n}\n\n.events-list {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n}\n\n.event-item {\n  display: flex;\n  align-items: center;\n  gap: 6px;\n}\n\n.event-icon {\n  width: 12px;\n  height: 12px;\n  flex-shrink: 0;\n}\n\n.event-icon.done {\n  color: #34d399;\n}\n\n.event-icon.pending {\n  color: rgba(255, 255, 255, 0.3);\n}\n\n.event-text {\n  font-size: 11px;\n  color: rgba(255, 255, 255, 0.4);\n}\n\n.event-text.done {\n  color: rgba(255, 255, 255, 0.7);\n}\n</style>\n"],"sourceRoot":""}]);
